command_captures.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';
const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const b=JSON.parse(fs.readFileSync('docs/remediation/design/W10.01/baseline.json','utf8'));
const owned=new Set(b.owned.map(x=>x.path)), protectedPins=b.pins.filter(x=>!owned.has(x.path));
const mismatches=protectedPins.filter(x=>sha(x.path)!==x.sha256).map(x=>x.path);assert.deepEqual(mismatches,[]);
console.log(JSON.stringify({final_source_stop:{at:new Date().toISOString(),files:b.owned.map(x=>({path:x.path,sha256:sha(x.path)}))},protected_source_comparison:{checked:protectedPins.length,mismatches},records:{baseline:{path:'docs/remediation/design/W10.01/baseline.json',sha256:sha('docs/remediation/design/W10.01/baseline.json')},plan:{path:'docs/remediation/design/W10.01/plan.md',sha256:sha('docs/remediation/design/W10.01/plan.md')},admission:{path:'docs/remediation/evidence/W10.01/admission.json',sha256:sha('docs/remediation/evidence/W10.01/admission.json')}}}));
NODE
